-- SPOT-05 명소 이야기 (11/8). 명소 화면에서 카드를 뒤집으면 보이는 원문입니다. 방문 전에도 읽을 수 있습니다.
-- 🟡 초안이라 제출 전에 공식 자료와 사실 확인이 필요합니다. AI 말투 변환은 하지 않고 원문을 그대로 씁니다.
ALTER TABLE spots ADD COLUMN story VARCHAR(500);

UPDATE spots SET story = '팔공산 관봉 꼭대기에 앉은 돌부처입니다. 머리에 넓적한 돌을 갓처럼 쓰고 있어 갓바위라 불려요. 정성껏 빌면 한 가지 소원은 꼭 들어준다는 이야기가 전해져, 지금도 시험을 앞둔 사람들이 가파른 돌계단을 오릅니다.' WHERE name = '팔공산 갓바위';
UPDATE spots SET story = '조선 시대 영남의 선비들이 한양으로 과거를 보러 넘던 고갯길입니다. 문경이라는 이름에는 경사스러운 소식을 듣는다는 뜻이 담겨 있다고 해요. 길가의 책바위에는 돌을 쌓으며 합격을 빌던 마음이 지금도 이어지고 있습니다.' WHERE name = '문경새재 과거길';
UPDATE spots SET story = '한반도를 호랑이에 빗대면 꼬리에 해당하는 곳이라 호미곶이라 불립니다. 새천년을 맞아 세운 상생의 손은 바다와 육지에서 서로 마주 보고 있어요. 해마다 새해 첫날이면 첫 해를 보려는 사람들이 이곳에 모입니다.' WHERE name = '호미곶 해맞이광장';
UPDATE spots SET story = '신라 때 처음 세워진 팔공산의 오래된 절입니다. 절을 다시 지을 때 겨울인데도 오동나무 꽃이 피었다고 해서 동화사라는 이름이 붙었다고 전해져요. 추운 계절에 피어난 꽃처럼, 때를 기다리는 마음을 생각하게 하는 곳입니다.' WHERE name = '동화사';
UPDATE spots SET story = '신라 사람 김대성이 세웠다고 전해지는 절과 돌로 만든 석굴입니다. 돌 하나하나를 다듬어 올린 정성은 천 년이 지난 지금도 남아 있어요. 1995년에 두 곳이 함께 유네스코 세계유산에 올랐습니다.' WHERE name = '불국사·석굴암';
UPDATE spots SET story = '의상대사가 세운 절로, 이름은 떠 있는 돌이라는 뜻입니다. 절을 지을 때 큰 바위가 떠올라 방해하는 무리를 물리쳤다는 이야기가 전해져요. 무량수전 앞에 서면 소백산 능선이 겹겹이 펼쳐집니다.' WHERE name = '부석사';
UPDATE spots SET story = '신라 사람들이 부처의 산으로 여긴 곳입니다. 골짜기마다 바위에 새긴 불상과 돌탑이 남아 있어 산 전체가 야외 박물관 같아요. 수백 년에 걸쳐 돌에 마음을 새긴 흔적을 걸으며 만날 수 있습니다.' WHERE name = '경주 남산';
UPDATE spots SET story = '동해를 따라 이어지는 영덕 블루로드 위의 공원입니다. 대게의 고장답게 근처 창포말등대는 대게 집게 모양을 하고 있어요. 탁 트인 바다 위로 떠오르는 해를 보며 새 다짐을 하기 좋은 곳입니다.' WHERE name = '영덕 해맞이공원';
UPDATE spots SET story = '신라 문무왕이 잠들었다고 전해지는 바다 위 바위입니다. 왕은 죽어서 용이 되어 나라를 지키겠다는 유언을 남겼다고 해요. 파도를 맞으며 그 자리를 지키는 대왕암은 오래 이어지는 다짐을 떠올리게 합니다.' WHERE name = '문무대왕릉';
UPDATE spots SET story = '안동 하회마을 한가운데 서 있는 약 600년 된 느티나무입니다. 마을을 지키는 신목으로 여겨져 왔고, 사람들은 소원을 적은 종이를 나무 둘레에 매달아요. 수많은 소원지가 나무를 감싸고 있는 모습이 인상적인 곳입니다.' WHERE name = '하회마을 삼신당 신목';
